from itertools import permutations
res=set()
for p in permutations(["M","F","H"]):
    cyc=["G"]+list(p)
    c=lambda a,b: cyc[(cyc.index(a)+1)%4]==b
    if c("G","M") and c("F","H"): res.add(cyc[2])
assert res=={"F"}
ans=res.pop()
opts={"A":"S","B":"F","C":"H","D":"M"}
assert ans==opts["B"]
for k in "ACD": assert ans!=opts[k]

